        add("item.fargo_soul.necromancer_soul.attribute.2", "Skeletons and Wither Skeletons guaranteed to drop skulls", "持有者杀死骷髅或凋零骷髅必定额外掉落对应头颅");
        add("item.fargo_soul.necromancer_soul.attribute.3", "Killing undead creatures heals wielder for 20% of target max HP", "持有者杀死的目标为亡灵生物时，为持有者恢复20%目标最大生命值的生命值");
        add("item.fargo_soul.necromancer_soul.tooltip.1", "\"Welcome to the Bone Zone\"", "“欢迎来到骸骨领域”");
        add("item.fargo_soul.ninja_soul", "Ninja Enchantment", "忍者魔石");
        add("item.fargo_soul.ninja_soul.attribute.1", "Reduces detection range of enemies", "降低目标发现持有者的范围");
        add("item.fargo_soul.ninja_soul.attribute.2", "Melee damage builds up to 300%; reset after attacking", "近战攻击力逐渐提高至300%，攻击后清空增益");
        add("item.fargo_soul.ninja_soul.tooltip.1", "\"Waiting for the right moment...\"", "“等待正确的时机......”");
        add("item.fargo_soul.penetrating_ninja_soul", "Shinobi Infiltrator Enchantment", "渗透忍者魔石");
        add("item.fargo_soul.penetrating_ninja_soul.attribute.1", "Grants dash ability", "使持有者获得冲刺能力");
        add("item.fargo_soul.penetrating_ninja_soul.attribute.2", "Colliding with enemies during dash deals 10% max HP wither damage and massive knockback", "冲刺时撞击敌人，造成10%持有者最大生命值的凋零伤害与大量击退");
        add("item.fargo_soul.penetrating_ninja_soul.attribute.3", "Invincibility and wall-phasing for 1s after dashing; 20s cooldown", "持有者冲刺后的1秒内免疫一切伤害并可以穿过墙壁，该效果有20秒冷却时间");
        add("item.fargo_soul.penetrating_ninja_soul.tooltip.1", "\"The village hidden in walls\"", "“藏匿于墙中的村庄”");
        add("item.fargo_soul.earth_power", "Power of Earth", "大地之力");
        add("item.fargo_soul.earth_power.attribute.1", "Enhanced Adamantite - +15% move speed at max attack speed stacks", "强化-精金-攻击速度增益达到最大值时，移动速度额外提升15%");
        add("item.fargo_soul.earth_power.attribute.2", "Enhanced Cobalt - Reduced explosion CD, increased radius and damage, longer Oiled duration", "强化-钴蓝-爆炸冷却减少，爆炸范围提升，爆炸伤害提升，延长爆炸所施加浸油减益的时间");
        add("item.fargo_soul.earth_power.attribute.3", "Enhanced Mithril - Attack speed buff duration increased to 6s", "强化-秘银-攻击速度增益的持续时间提升至6秒");
        add("item.fargo_soul.earth_power.attribute.4", "Enhanced Orichalcum - Increased petal chance, Orichalcum Poisoning level +1", "强化-山铜-召唤花瓣的概率提升，施加山铜中毒的等级+1");
        add("item.fargo_soul.earth_power.attribute.5", "Enhanced Palladium - Increased life regen chance, max life regen level +1", "强化-钯金-获取生命恢复增益的概率提升，生命恢复增益的等级上限+1");
        add("item.fargo_soul.earth_power.attribute.6", "Enhanced Titanium - Titanium Shield knocks back nearby enemies when blocking", "强化-钛金-钛金护盾抵挡伤害时，击退周围的目标");
        add("item.fargo_soul.earth_power.attribute.7", "Build Earth Energy after 2s of not attacking; consumed on attack", "不攻击2秒后会积聚大地能量，攻击会消耗能量");
        add("item.fargo_soul.earth_power.attribute.8", "At max energy: +100% Attack Speed, +5 HP/s Regen, +25% DR", "攻击速度，生命回复，伤害减免会随能量积攒而增加，至多增加100%攻击速度，每秒5点生命恢复，25%伤害减免");
        add("item.fargo_soul.earth_power.attribute.9", "Attacks deal bonus damage based on energy, up to 40%", "充能后攻击会造成攻击伤害一定比例的额外伤害，随能量积攒而增加比例，至多40%");
        add("item.fargo_soul.earth_power.tooltip.1", "\"Gaia's blessing shines upon you\"", "“盖亚的祝福照耀着你”");
        add("item.fargo_soul.adamantite_soul", "Adamantite Enchantment", "精金魔石");
        add("item.fargo_soul.adamantite_soul.attribute.1", "Each attack grants 5% attack speed, max 8 stacks; reset after 5s", "持有者每次攻击会提高5%攻击速度，最高叠加8层，5秒不攻击清空");
        add("item.fargo_soul.adamantite_soul.attribute.2", "At max stacks, attacks have a chance to cause targets to lose aggro", "攻击速度增益达到最大值时，持有者的攻击有概率使目标丢失索敌");
        add("item.fargo_soul.adamantite_soul.tooltip.1", "\"Chaos\"", "“混乱”");
        add("item.fargo_soul.cobalt_soul", "Cobalt Enchantment", "钴蓝魔石");
        add("item.fargo_soul.cobalt_soul.attribute.1", "Inflicts Oiled on nearby targets", "对持有者附近的目标施加浸油减益");
        add("item.fargo_soul.cobalt_soul.attribute.2", "Oiled targets take greatly increased fire damage", "被浸油影响的目标受到的火焰伤害大幅增加");
        add("item.fargo_soul.cobalt_soul.attribute.3", "Generate a small explosion and apply Oiled when damaged; 3s cooldown", "受到伤害时，在持有者位置产生小爆炸，并对附近的目标施加浸油减益，该效果有3秒冷却时间");
        add("item.fargo_soul.cobalt_soul.attribute.4", "Immunity to Oiled", "免疫浸油");
        add("item.fargo_soul.cobalt_soul.tooltip.1", "\"Can't believe it's not Palladium\"", "“真不敢相信这竟然不是钯金”");
        add("item.fargo_soul.mithril_soul", "Mithril Enchantment", "秘银魔石");
        add("item.fargo_soul.mithril_soul.attribute.1", "Attacking after 5s of idle time grants +50% attack speed", "持有者在5秒不攻击后开始攻击会获得攻击速度增益，提升50%攻击速度");
        add("item.fargo_soul.mithril_soul.attribute.2", "Buff lost 3s after attacking", "持有者攻击目标后3秒失去增益");
        add("item.fargo_soul.mithril_soul.tooltip.1", "\"Weapon knowledge seeps into your mind\"", "“你感觉武器的知识渗透进你的脑海中”");
        add("item.fargo_soul.orichalcum_soul", "Orichalcum Enchantment", "山铜魔石");
        add("item.fargo_soul.orichalcum_soul.attribute.1", "Chance to summon petals on hit dealing [1 + 5% damage] magic damage and 5s Orichalcum Poisoning", "持有者攻击时有概率召唤花瓣落到目标的身上，造成额外[1+5%造成伤害]的魔法伤害并施加5秒山铜中毒减益");
        add("item.fargo_soul.orichalcum_soul.attribute.2", "Orichalcum Poisoning deals continuous damage and increases poison damage taken to 350%", "山铜中毒会对目标持续造成魔法伤害，并将目标受到的所有毒性伤害提升至350%");
        add("item.fargo_soul.orichalcum_soul.attribute.3", "Immunity to Orichalcum Poisoning", "免疫山铜中毒");
        add("item.fargo_soul.orichalcum_soul.tooltip.1", "\"Nature blesses you\"", "“自然祝福着你”");
        add("item.fargo_soul.palladium_soul", "Palladium Enchantment", "钯金魔石");
        add("item.fargo_soul.palladium_soul.attribute.1", "Attacks have a chance to grant 2s of Regeneration", "持有者攻击时有概率给予2秒生命恢复增益");
        add("item.fargo_soul.palladium_soul.attribute.2", "Stacks refresh duration and increase Regen level, up to level 3", "每次获取增益会刷新生命恢复的持续时间，并提升生命恢复增益的等级，上限3级");
        add("item.fargo_soul.palladium_soul.attribute.3", "Gain Absorption for every 10 HP recovered", "持有者每恢复10生命值额外获取伤害吸收增益");
        add("item.fargo_soul.palladium_soul.tooltip.1", "\"You feel your wounds slowly healing\"", "“你感到你的伤口在慢慢愈合”");
        add("item.fargo_soul.titanium_soul", "Titanium Enchantment", "钛金魔石");
        add("item.fargo_soul.titanium_soul.attribute.1", "Generate a Titanium Shield after 20s of no damage, blocking next hit", "持有者每20秒不受伤害会生成一个钛金护盾，免疫下次受到伤害");
        add("item.fargo_soul.titanium_soul.attribute.2", "If shield is down, gain up to 25% move speed based on missing health", "钛金护盾未生成时，根据持有者已损生命值比例提升移动速度，最高增加25%移动速度");
        add("item.fargo_soul.titanium_soul.tooltip.1", "\"Who needs to dodge with absolute defense?\"", "“有了绝对防御后，谁还需要躲避呢？”");
        add("item.fargo_soul.forest_power", "Power of Forest", "森林之力");
        add("item.fargo_soul.forest_power.attribute.1", "Enhanced Ebonwood - Corruption limit increased to 200", "强化-乌木-腐化目标的上限提升至200点");
        add("item.fargo_soul.forest_power.attribute.2", "Enhanced Palm Wood - Attacks on burning targets may cause explosions", "强化-棕榈木-持有者攻击燃烧的目标时，有概率产生小型爆炸");
        add("item.fargo_soul.forest_power.attribute.3", "Enhanced Pearlwood - Additional critical strike check count +1", "强化-珍珠木-额外进行的暴击判定次数+1");
        add("item.fargo_soul.forest_power.attribute.4", "Enhanced Boreal Wood - Increases snowball generation speed", "强化-针叶木-提升产生雪球的速度");
        add("item.fargo_soul.forest_power.attribute.5", "Enhanced Rich Mahogany - Increases traction strength", "强化-红木-提升牵引力度");
        add("item.fargo_soul.forest_power.attribute.6", "Enhanced Shadewood - Life siphoned increased to 3 points", "强化-阴影木-汲取的生命值提升至3点");
        add("item.fargo_soul.forest_power.attribute.7", "Enhanced Wood - Further increases discounts", "强化-木-进一步提升折扣");
        add("item.fargo_soul.forest_power.attribute.8", "Grants a Wither Aura", "使持有者拥有凋零光环");
        add("item.fargo_soul.forest_power.attribute.9", "Hitting enemies in the aura fires snowballs; 0.25s cooldown", "击中光环内的敌人时会发射雪球，该效果有0.25秒冷却时间");
        add("item.fargo_soul.forest_power.attribute.10", "Attacking Withered enemies deals 15 bonus damage", "持有者攻击被凋零效果影响的敌人时，造成的伤害额外提升15点");
        add("item.fargo_soul.forest_power.attribute.11", "Gain 30% DR and 200% Thorns while in the air; 8s cooldown", "在空中时，获得30%伤害减免和200%荆棘效果，该效果有8秒冷却时间");
        add("item.fargo_soul.forest_power.attribute.12", "Gain 20% DR against enemies you have previously killed", "持有者受到曾击杀过的目标伤害时，获得20%伤害减免");
        add("item.fargo_soul.forest_power.tooltip.1", "\"Very hard\"", "“很硬”");
        add("item.fargo_soul.ebony_wood_soul", "Ebonwood Enchantment", "乌木魔石");
        add("item.fargo_soul.ebony_wood_soul.attribute.1", "Nearby targets are gradually Corrupted, up to 100 points", "在持有者周围的目标会被逐渐腐化，腐化值上限为100点");
        add("item.fargo_soul.ebony_wood_soul.attribute.2", "Each point reduces target damage by 0.05% and increases damage taken by 0.1%", "每点腐化值降低目标对持有者的伤害0.05%，提升持有者对目标的伤害0.1%");
        add("item.fargo_soul.ebony_wood_soul.attribute.4", "Immunity to Corruption", "免疫腐化");
        add("item.fargo_soul.ebony_wood_soul.tooltip.1", "\"Potential not fully tapped\"", "“潜力未完全开发”");
        add("item.fargo_soul.palm_wood_soul", "Palm Wood Enchantment", "棕榈木魔石");
        add("item.fargo_soul.palm_wood_soul.attribute.1", "Attacks ignite targets or extend burn duration up to 30s", "持有者攻击时，点燃目标或延长目标的燃烧时间，至多延长至30秒");
        add("item.fargo_soul.palm_wood_soul.attribute.2", "Fire damage taken by nearby enemies increased to 150%", "持有者周围的目标受到的火焰伤害提升至150%");
        add("item.fargo_soul.palm_wood_soul.tooltip.1", "\"Surprisingly peaceful\"", "“出奇的宁静”");
        add("item.fargo_soul.pearl_wood_soul", "Pearlwood Enchantment", "珍珠木魔石");
        add("item.fargo_soul.pearl_wood_soul.attribute.1", "Crit damage multiplier increased to 130%", "持有者攻击暴击时，暴击伤害系数提升至130%");
        add("item.fargo_soul.pearl_wood_soul.attribute.2", "Non-crits have a 25% chance to be re-rolled as a crit", "持有者攻击没有暴击时，额外进行25%概率的暴击判定");
        add("item.fargo_soul.pearl_wood_soul.tooltip.1", "\"Too little, too late...\"", "“太少了，太晚了……”");
        add("item.fargo_soul.pine_wood_soul", "Boreal Wood Enchantment", "针叶木魔石");
        add("item.fargo_soul.pine_wood_soul.attribute.1", "Generates snowballs above your head to attack random nearby enemies", "持有者的头顶会产生雪球攻击周围随机目标");
        add("item.fargo_soul.pine_wood_soul.tooltip.1", "\"Cold and cool\"", "“又冷又酷”");
        add("item.fargo_soul.rose_wood_soul", "Rich Mahogany Enchantment", "红木魔石");
        add("item.fargo_soul.rose_wood_soul.attribute.1", "Attacking airborne targets pulls them slightly towards you", "持有者攻击空中目标时，会将目标向持有者方向牵引一小段距离");
        add("item.fargo_soul.rose_wood_soul.attribute.2", "Immunity to traction", "免疫牵引");
        add("item.fargo_soul.rose_wood_soul.tooltip.1", "\"Guaranteed to hook you\"", "“保证钩到你”");
        add("item.fargo_soul.shadow_wood_soul", "Shadewood Enchantment", "阴影木魔石");
        add("item.fargo_soul.shadow_wood_soul.attribute.1", "Apply a Siphon Mark to a random nearby target every 5s", "每5秒为持有者周围随机一个目标附加汲取标记");
        add("item.fargo_soul.shadow_wood_soul.attribute.2", "When a marked target attacks you, siphon 2 HP and remove mark", "带有汲取标记的目标攻击持有者时，持有者将汲取目标2点生命值并移除标记");
        add("item.fargo_soul.shadow_wood_soul.tooltip.1", "\"Surprisingly clean\"", "“出奇的干净”");
        add("item.fargo_soul.wood_soul", "Wood Enchantment", "木魔石");
        add("item.fargo_soul.wood_soul.attribute.1", "Increased villager discounts, permanent good reputation in villages", "村民折扣增加，持有者在村庄中永远拥有好声望");
        add("item.fargo_soul.wood_soul.tooltip.1", "\"A trick hated by shopkeepers\"", "“被店主们讨厌的诡计”");
        add("item.fargo_soul.wood_soul.tooltip.2", "\"Humble beginnings...\"", "“卑微的开始……”");
        add("item.fargo_soul.life_power", "Power of Life", "生命之力");
        add("item.fargo_soul.life_power.attribute.1", "Enhanced Turtle - Increased cactus burst chance, count, and damage", "强化-乌龟-爆出仙人掌的概率提升，数量提升，伤害提升");
        add("item.fargo_soul.life_power.attribute.2", "Enhanced Bee - Bees and flower-contact healing speed increased", "强化-蜜蜂-周围蜜蜂的恢复速度加快，持有者接触花朵时恢复生命值的速度加快");
        add("item.fargo_soul.life_power.attribute.3", "Enhanced Beetle - Max Beetle Endurance +1, Max Beetle Might +2", "强化-甲虫-甲虫耐力层数上限+1，甲虫力量层数上限+2");
        add("item.fargo_soul.life_power.attribute.4", "Enhanced Pumpkin - Explosion damage increased, enemies hit drop pumpkin seeds", "强化-南瓜-南瓜的爆炸伤害提升，被爆炸伤害的目标会爆出南瓜子");
        add("item.fargo_soul.life_power.attribute.5", "Enhanced Spider - Minion crit to 40% and 200% damage, no cap on minion crit bonus", "强化-蜘蛛-仆从暴击率提升至40%，仆从暴击伤害提升至200%，仆从暴击增伤不再有上限");
        add("item.fargo_soul.life_power.attribute.6", "Provides powerful wing flight", "提供强大的翅膀飞行能力");
        add("item.fargo_soul.life_power.attribute.7", "Heal when touching flowers, spawning bees and granting 10s Ambrosia", "触碰花朵时会回复血量，同时产生大量蜜蜂，获得10秒仙馔密酒增益");
        add("item.fargo_soul.life_power.attribute.8", "Ambrosia: +30% Damage, +20% DR, and +5 HP/s Regen", "仙馔密酒增益增加30%伤害，增加20%伤害减免和5每秒生命恢复");
        add("item.fargo_soul.life_power.attribute.9", "Ambrosia increases minion crit damage to 400%", "仙馔密酒增益会使仆从的暴击伤害提升至400%");
        add("item.fargo_soul.life_power.attribute.10", "Reflects 500% contact damage", "反弹500%的接触伤害");
        add("item.fargo_soul.life_power.tooltip.1", "\"Few creatures dare defy your will\"", "“罕有生灵敢违背你的意愿”");
        add("item.fargo_soul.bee_soul", "Bee Enchantment", "蜜蜂魔石");
        add("item.fargo_soul.bee_soul.attribute.1", "Allows short flight", "允许持有者短时间飞行");
        add("item.fargo_soul.bee_soul.attribute.2", "Nearby bees recover HP and won't attack you", "使持有者附近的蜜蜂逐渐恢复生命值，蜜蜂不会攻击持有者");
        add("item.fargo_soul.bee_soul.attribute.3", "Slowly recover HP when touching flowers", "持有者接触花朵时缓慢恢复生命值");
        add("item.fargo_soul.bee_soul.attribute.4", "Nearby bees assist in attacking your target", "持有者攻击目标时，周围的蜜蜂会协同攻击目标");
        add("item.fargo_soul.bee_soul.attribute.5", "Drinking honey heals 5% max HP and summons a bee", "持有者饮用蜂蜜时，额外恢复5%持有者最大生命值的生命值并召唤一只蜜蜂");
        add("item.fargo_soul.bee_soul.attribute.6", "You cannot damage bees", "持有者不会对蜜蜂造成伤害");
        add("item.fargo_soul.bee_soul.attribute.7", "Immunity to fall damage", "免疫摔落伤害");
        add("item.fargo_soul.bee_soul.tooltip.1", "\"According to all known laws of aviation, there is no way a bee should be able to fly\"", "“根据目前所知的所有航空原理，蜜蜂应该根本不可能会飞”");
        add("item.fargo_soul.beetle_soul", "Beetle Enchantment", "甲虫魔石");
        add("item.fargo_soul.beetle_soul.attribute.1", "Allows short flight", "允许持有者短时间飞行");
        add("item.fargo_soul.beetle_soul.attribute.2", "Gain Beetle Endurance every 7s, max 2 stacks", "持有者每7秒获得1层甲虫耐力，最多叠加2层");
        add("item.fargo_soul.beetle_soul.attribute.3", "Each stack gives +15% DR; lost when damaged", "每层甲虫耐力增加持有者15%伤害减免，每次受到伤害时失去1层甲虫耐力");
        add("item.fargo_soul.beetle_soul.attribute.4", "Gain Beetle Might on hit, max 4 stacks", "持有者攻击目标时获得1层甲虫力量，最多叠加4层");
        add("item.fargo_soul.beetle_soul.attribute.5", "Each stack gives +3 Armor Pen; lose 1 stack per second", "每层甲虫力量增加持有者3点护甲穿透，每秒失去1层甲虫力量");
        add("item.fargo_soul.beetle_soul.attribute.6", "Arthropods will not attack you", "节肢动物们不会主动攻击持有者");
        add("item.fargo_soul.beetle_soul.tooltip.1", "\"Invisible fecal life flows through your veins\"", "“你的血管里流淌着看不见的粪便生命”");
        add("item.fargo_soul.pumpkin_soul", "Pumpkin Enchantment", "南瓜魔石");
        add("item.fargo_soul.pumpkin_soul.attribute.1", "Plant pumpkin seeds while moving if on suitable soil", "如果脚下可以种植南瓜，持有者在移动时将会种下南瓜种子");
        add("item.fargo_soul.pumpkin_soul.attribute.2", "Stepping on ripe pumpkins causes them to explode", "踩在成熟的南瓜上时会使南瓜产生爆炸");
        add("item.fargo_soul.pumpkin_soul.attribute.3", "Speeds up pumpkin growth nearby", "加速持有者周围南瓜的生长速度");
        add("item.fargo_soul.pumpkin_soul.tooltip.1", "\"Your sudden craving for pumpkins will never be satisfied\"", "“你对南瓜的突发渴望永远不会得到满足”");
        add("item.fargo_soul.spider_soul", "Spider Enchantment", "蜘蛛魔石");
        add("item.fargo_soul.spider_soul.attribute.1", "Minions gain +20% crit rate and 150% crit damage", "使持有者的仆从获得20%暴击率和150%暴击伤害");
        add("item.fargo_soul.spider_soul.attribute.2", "Minion crit damage bonus capped at 100", "持有者仆从暴击增加的伤害上限为100点");
        add("item.fargo_soul.spider_soul.tooltip.1", "\"Arachnophobe? Kill him with spiders!\"", "“蜘蛛恐惧者？作为惩罚，让他被蜘蛛干掉吧！”");
        add("item.fargo_soul.turtle_soul", "Turtle Enchantment", "乌龟魔石");
        add("item.fargo_soul.turtle_soul.attribute.1", "Reflects 60% contact damage; scales down with distance to 10%", "持有者被目标攻击时反弹60%接触伤害，距离越远反弹的伤害越低，至多衰减至接触伤害of the 10%");
        add("item.fargo_soul.turtle_soul.attribute.2", "At <50% HP: reflects 80% damage regardless of distance with knockback", "持有者生命值低于50%时，反弹的伤害提升至80%接触伤害，反弹伤害不再随距离衰减，反弹伤害时附加击退");
        add("item.fargo_soul.turtle_soul.attribute.3", "At <25% HP: gain Shell granting 4% max HP damage block", "持有者生命值低于25%时，持有者会获得龟壳，龟壳存在时，持有者获得相当于4%最大生命值的伤害格挡");
        add("item.fargo_soul.turtle_soul.attribute.4", "Shell vanishes >25% HP or breaks on lethal hit; 120s cooldown", "龟壳会在持有者高于25%生命值时消失，或在受到大于持有者当前生命值的伤害时破碎，并完全抵挡此伤害，龟壳破碎后120秒不会再生成龟壳");
        add("item.fargo_soul.turtle_soul.attribute.5", "Damaged: chance to release cacti; kills burst into more cacti", "受到攻击时，有概率释放出一堆仙人掌，被仙人掌扎死的敌人会爆裂出更多仙人掌");
        add("item.fargo_soul.turtle_soul.attribute.6", "Immunity to cactus damage", "免疫仙人掌伤害");
        add("item.fargo_soul.turtle_soul.tooltip.1", "\"You have a sudden urge to hide in a shell\"", "“你突然有一种想躲进壳里的冲动”");
        add("item.fargo_soul.nature_power", "Power of Nature", "自然之力");
        add("item.fargo_soul.nature_power.attribute.1", "Enhanced Crimson - Siphon range increased", "强化-猩红-汲取范围提升");
        add("item.fargo_soul.nature_power.attribute.2", "Enhanced Frost - Max snowballs increased to 20", "强化-冰霜-雪球的存在上限提升至20个");
        add("item.fargo_soul.nature_power.attribute.3", "Enhanced Chlorophyte - Attack interval reduced, inflicts Poison", "强化-叶绿-攻击间隔降低，并且会对目标施加中毒");
        add("item.fargo_soul.nature_power.attribute.4", "Enhanced Lava - Burning targets nearby may explode", "强化-熔岩-持有者周围燃烧的目标有概率产生爆炸");
        add("item.fargo_soul.nature_power.attribute.5", "Enhanced Mushroom - Stews grant Mush-Power for 10s", "强化-蘑菇-持有者食用蘑菇煲后获得蘑菇力量增益持续10秒");
        add("item.fargo_soul.nature_power.attribute.6", "Enhanced Rain - Lightning chance increased during rain", "强化-雨云-在雨天时，召唤雷电的概率提升");
        add("item.fargo_soul.nature_power.attribute.7", "Nature Aura: deals damage and siphons HP every 0.5s; damage x4 if not hit for 4s", "持有者拥有一个自然光环，每过0.5秒对光环内的敌人造成伤害并吸取生命值，基础伤害为2，每4秒不受击可增加一倍伤害，最高4倍");
        add("item.fargo_soul.nature_power.attribute.8", "Summons 5 Chlorophyte Crystals firing 20 damage lasers", "召唤5个围绕持有者旋转的叶绿水晶，水晶会向敌怪发射激光，激光基础伤害为20");
        add("item.fargo_soul.nature_power.attribute.9", "Crystal hits spawn 5 mushrooms dealing 20% of laser damage", "叶绿水晶击中后会产生5个蘑菇，蘑菇伤害为激光造成伤害的20%");
        add("item.fargo_soul.nature_power.attribute.10", "Mushrooms restore +50 HP; Mush-Power increases aura size", "持有者食用蘑菇可额外恢复50点生命值，拥有蘑菇力量时增加光环大小");
        add("item.fargo_soul.nature_power.attribute.11", "Attacks slow targets", "持有者攻击会使向目标施加缓慢");
        add("item.fargo_soul.nature_power.attribute.12", "Ranged damage taken reduced by 15", "远程射弹对持有者造成的伤害降低15点");
        add("item.fargo_soul.nature_power.tooltip.1", "\"Travel through every secret corner of the wilderness\"", "“走遍荒野的每一个秘密角落”");
        add("item.fargo_soul.crimson_soul", "Crimson Enchantment", "猩红魔石");
        add("item.fargo_soul.crimson_soul.attribute.1", "Siphon 10% of health lost by nearby targets", "周围的目标每次受伤时，持有者都会汲取目标失去生命值的10%");
        add("item.fargo_soul.crimson_soul.attribute.2", "Siphon scales up to 40% based on missing health", "持有者已损生命值比例越高，汲取的生命值越多，至多汲取目标失去生命值的40%");
