        add("item.fargo_soul.frost_soul", "Frost Enchantment", "冰霜魔石");
        add("item.fargo_soul.frost_soul.attribute.1", "Generates 1 snowball per second, up to 10", "每秒在持有者周围生成1个雪球，最多可同时存在10个");
        add("item.fargo_soul.frost_soul.attribute.2", "Fires a snowball at nearby targets every 0.25s", "每0.25秒发射1个雪球攻击附近的目标");
