    private void add(String key, String enDesc, String zhDesc) {
        LanguageProviderAccessor accessor = (LanguageProviderAccessor) this;
        String locale = accessor.getLocale();
        if (locale.equals("en_us")) {
            add(key, enDesc);
        } else if (locale.equals("zh_cn")) {
            add(key, zhDesc);
        }
    }

